const SCALE = 6;
const WORKDAYS = 250;
const SETTLE_DAYS = 5;
const NODES = nodes;
const NAMES = names;
const BB = bbox;
const EDGES = edges;
const BLD = buildings;
const inBox = (x, z, m = 0) => x > BB.x0 - m && x < BB.x1 + m && z > BB.z0 - m && z < BB.z1 + m;
function mulberry32(a) {
	return () => {
		a |= 0;
		a = a + 1831565813 | 0;
		let t = Math.imul(a ^ a >>> 15, 1 | a);
		t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
		return ((t ^ t >>> 14) >>> 0) / 4294967296;
	};
}
const hash2 = (a, b) => {
	let h = Math.imul(a + 2654435769, 2246822507) ^ Math.imul(b + 2135587861, 3266489909);
	h ^= h >>> 13;
	h = Math.imul(h, 668265263);
	h ^= h >>> 16;
	return (h >>> 0) / 4294967296;
};
